package cn.governance;

import java.util.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.commons.csv.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.apache.poi.ss.usermodel.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;

@Service
public class BatchIntake {
    static final List<String> FIELDS=List.of("personName","idCard","phone","eventTime","description","categoryId","disputeId");
    static final Set<String> REQUIRED=Set.of("eventTime","description","categoryId","disputeId");
    public record Mapping(String name,long sourceId,Map<String,String> columns,Map<String,String> categories,Map<String,String> disputes,String timeFormat,Boolean specialReport,Long receivedDepartmentId){}
    private final JdbcTemplate jdbc;private final AccountService accounts;private final IntakeService intake;private final CatalogService catalog;private final ObjectMapper json;private final KeywordRecognition hashes;private final ManagementAudit audit;
    public BatchIntake(JdbcTemplate jdbc,AccountService accounts,IntakeService intake,CatalogService catalog,ObjectMapper json,KeywordRecognition hashes,ManagementAudit audit){this.jdbc=jdbc;this.accounts=accounts;this.intake=intake;this.catalog=catalog;this.json=json;this.hashes=hashes;this.audit=audit;}
    String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalStateException(e);}}
    private void lock(){jdbc.queryForObject("SELECT id FROM tb_intake_lock WHERE id=1 FOR UPDATE",Long.class);}
    AccountService.Account reporter(Authentication a){var actor=accounts.current(a);if(!actor.canReadAll()&&!actor.canReadDepartment())throw new ResponseStatusException(HttpStatus.FORBIDDEN);return actor;}
    public Object mappings(Authentication a){reporter(a);return jdbc.queryForList("SELECT * FROM tb_source_mapping ORDER BY id DESC");}
    @Transactional public Object mapping(Authentication a,Mapping m){lock();var actor=intake.analyst(a);InputChecks.text(m.name(),100,"映射名称");InputChecks.require(m.columns()!=null&&m.columns().keySet().containsAll(REQUIRED)&&FIELDS.containsAll(m.columns().keySet())&&m.columns().values().stream().allMatch(v->v!=null&&!v.isBlank())&&new HashSet<>(m.columns().values()).size()==m.columns().size(),"字段映射缺少必填列或重复");InputChecks.require(m.categories()!=null&&m.disputes()!=null,"请提供分类别名映射");InputChecks.require(Set.of("ISO","yyyy/MM/dd HH:mm:ss","yyyy-MM-dd HH:mm:ss").contains(Objects.toString(m.timeFormat(),"")),"时间转换格式无效");InputChecks.require(catalog.sourceOptions(a).stream().anyMatch(s->s.id()==m.sourceId()),"来源无效");long id=JdbcIds.insert(jdbc,"INSERT INTO tb_source_mapping(source_id,name,payload,version) VALUES (?,?,?,COALESCE((SELECT MAX(v.version)+1 FROM tb_source_mapping v WHERE v.source_id=? AND v.name=?),1))",m.sourceId(),m.name(),encode(m),m.sourceId(),m.name());audit.record(actor,"SOURCE_MAPPING",id,null,m);return jdbc.queryForMap("SELECT * FROM tb_source_mapping WHERE id=?",id);}
    Mapping mapping(long source,Long id){if(id==null){var columns=new LinkedHashMap<String,String>();FIELDS.forEach(f->columns.put(f,f));return new Mapping("统一模板",source,columns,Map.of(),Map.of(),"ISO",null,null);}try{var m=json.readValue(jdbc.queryForObject("SELECT payload FROM tb_source_mapping WHERE id=?",String.class,id),Mapping.class);InputChecks.require(m.sourceId()==source,"映射来源不符");return m;}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}}
    public byte[] template(Authentication a,long source,Long mappingId,String format){reporter(a);var m=mapping(source,mappingId);var header=new ArrayList<>(m.columns().values());try{if("xlsx".equals(format)){try(var book=new XSSFWorkbook();var output=new ByteArrayOutputStream()){var row=book.createSheet("导入模板").createRow(0);for(int i=0;i<header.size();i++)row.createCell(i).setCellValue(header.get(i));book.write(output);return output.toByteArray();}}var output=new StringWriter();try(var printer=new CSVPrinter(output,CSVFormat.DEFAULT)){printer.printRecord(header);}return ("\ufeff"+output).getBytes(StandardCharsets.UTF_8);}catch(IOException e){throw new IllegalStateException(e);}}
    @Transactional public Object upload(Authentication a,long source,Long mappingId,String filename,byte[] bytes){lock();var actor=reporter(a);InputChecks.require(bytes.length<=5_000_000,"文件最大5MB");InputChecks.require(catalog.sourceOptions(a).stream().anyMatch(s->s.id()==source),"来源无效");var m=mapping(source,mappingId);List<List<String>> rows=new ArrayList<>();
        try{if(filename.toLowerCase(Locale.ROOT).endsWith(".xlsx")){try(var book=new XSSFWorkbook(new ByteArrayInputStream(bytes))){InputChecks.require(book.getNumberOfSheets()==1,"仅支持单工作表xlsx");var sheet=book.getSheetAt(0);InputChecks.require(sheet.getLastRowNum()<=5000,"最多5000行");var formatter=new DataFormatter(Locale.ROOT);int width=sheet.getRow(0)==null?0:sheet.getRow(0).getLastCellNum();InputChecks.require(width>0&&width<=100,"表头无效");for(int n=0;n<=sheet.getLastRowNum();n++){List<String> values=new ArrayList<>();var row=sheet.getRow(n);for(int col=0;col<width;col++){var cell=row==null?null:row.getCell(col);InputChecks.require(cell==null||cell.getCellType()!=CellType.FORMULA,"不支持公式单元格");values.add(cell==null?"":formatter.formatCellValue(cell));}rows.add(values);}}}else{InputChecks.require(filename.toLowerCase(Locale.ROOT).endsWith(".csv"),"仅支持csv与xlsx");String text=new String(bytes,StandardCharsets.UTF_8).replaceFirst("^\ufeff","");try(var parser=CSVParser.parse(text,CSVFormat.DEFAULT)){for(var row:parser){rows.add(row.toList());InputChecks.require(rows.size()<=5001,"最多5000行");}}}}
        catch(IOException|IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"文件格式无效",e);}
        InputChecks.require(rows.size()>1,"文件没有数据行");var header=rows.removeFirst();InputChecks.require(new HashSet<>(header).size()==header.size()&&header.containsAll(m.columns().values()),"缺少映射列或列名重复");
        m=new Mapping(m.name(),m.sourceId(),m.columns(),m.categories(),m.disputes(),m.timeFormat(),actor.roles().contains("SPECIAL_REPORTER"),actor.canReadAll()?department(source):actor.departmentId());
        long batch=JdbcIds.insert(jdbc,"INSERT INTO tb_import_batch(owner_id,username,source_id,mapping_snapshot,original_file,filename) VALUES (?,?,?,?,?,?)",actor.id(),actor.username(),source,encode(m),bytes,filename);
        int number=2;for(var row:rows){Map<String,String> values=new LinkedHashMap<>();for(int i=0;i<header.size();i++)values.put(header.get(i),i<row.size()?row.get(i):"");jdbc.update("INSERT INTO tb_import_row(batch_id,line_number,payload) VALUES (?,?,?)",batch,number++,encode(values));}
        audit.record(actor,"BATCH_IMPORT",batch,null,Map.of("filename",filename,"rows",rows.size(),"mapping",m));return Map.of("id",batch);
    }
    public Object batches(Authentication a){var actor=reporter(a);return jdbc.queryForList("SELECT b.id,b.filename,b.created_at,COUNT(r.id) AS total,SUM(r.state='PENDING') AS pending,SUM(r.state='SUCCESS') AS succeeded,SUM(r.state='FAILED') AS failed,SUM(r.state='DUPLICATE') AS duplicates FROM tb_import_batch b JOIN tb_import_row r ON r.batch_id=b.id WHERE b.owner_id=? OR ?=1 GROUP BY b.id ORDER BY b.id DESC",actor.id(),actor.canReadAll());}
    Map<String,Object> batch(Authentication a,long id){var actor=reporter(a);return jdbc.queryForList("SELECT * FROM tb_import_batch WHERE id=? AND (owner_id=? OR ?=1)",id,actor.id(),actor.canReadAll()).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
    public Object rows(Authentication a,long id){batch(a,id);return jdbc.queryForList("SELECT * FROM tb_import_row WHERE batch_id=? ORDER BY line_number",id);}
    public byte[] original(Authentication a,long id){return (byte[])batch(a,id).get("original_file");}
    public byte[] failures(Authentication a,long id){var batch=batch(a,id);try{var m=json.readValue(batch.get("mapping_snapshot").toString(),Mapping.class);var out=new StringWriter();try(var printer=new CSVPrinter(out,CSVFormat.DEFAULT)){var header=new ArrayList<>(m.columns().values());header.add("原始行号");header.add("错误原因");printer.printRecord(header);for(var row:jdbc.queryForList("SELECT * FROM tb_import_row WHERE batch_id=? AND state='FAILED' ORDER BY line_number",id)){var value=json.readValue(row.get("payload").toString(),Map.class);List<Object> cells=new ArrayList<>();for(String h:m.columns().values())cells.add(csvSafe(Objects.toString(value.get(h),"")));cells.add(row.get("line_number"));cells.add(csvSafe(row.get("error").toString()));printer.printRecord(cells);}}return ("\ufeff"+out).getBytes(StandardCharsets.UTF_8);}catch(IOException e){throw new IllegalStateException(e);}}
    private String csvSafe(String value){return value.matches("^[=+@\\-].*")?"'"+value:value;}
    @Transactional public void process(long rowId){lock();var row=jdbc.queryForMap("SELECT r.*,b.username,b.source_id,b.mapping_snapshot,b.owner_id FROM tb_import_row r JOIN tb_import_batch b ON b.id=r.batch_id WHERE r.id=?",rowId);if(!"PENDING".equals(row.get("state")))return;
        try{var auth=new UsernamePasswordAuthenticationToken(accounts.loadUserByUsername(row.get("username").toString()),null);var actor=reporter(auth);InputChecks.require(actor.id()==((Number)row.get("owner_id")).longValue(),"原提交账号已变更");var m=json.readValue(row.get("mapping_snapshot").toString(),Mapping.class);
            InputChecks.require(m.receivedDepartmentId()!=null&&(actor.canReadAll()||actor.departmentId()==m.receivedDepartmentId()),"提交部门已变化或旧批次缺少接收依据，请重导");
            var roles=new ArrayList<>(actor.roles());roles.remove("SPECIAL_REPORTER");if(Boolean.TRUE.equals(m.specialReport()))roles.add("SPECIAL_REPORTER");
            var receivedActor=new AccountService.Account(actor.id(),actor.username(),actor.displayName(),actor.departmentId(),actor.departmentName(),roles);
            Authentication receivedAuth=new AccountService.TrustedIntakeToken(receivedActor);
            var raw=json.readValue(row.get("payload").toString(),Map.class);Map<String,String> v=new HashMap<>();m.columns().forEach((field,column)->v.put(field,Objects.toString(raw.get(column),"").strip()));
            String time=v.get("eventTime");if(!"ISO".equals(m.timeFormat()))time=java.time.LocalDateTime.parse(time,java.time.format.DateTimeFormatter.ofPattern(m.timeFormat())).toString();
            var entry=new IntakeService.Entry(v.get("personName"),v.get("idCard"),v.get("phone"),time,v.get("description"),((Number)row.get("source_id")).longValue(),classification(v.get("categoryId"),m.categories()),classification(v.get("disputeId"),m.disputes()),actor.canReadAll()?m.receivedDepartmentId():null);
            var result=receive(receivedAuth,entry,"FILE:"+actor.id()+":"+m.sourceId(),hashes.fingerprint(entry));jdbc.update("UPDATE tb_import_row SET state=?,record_id=?,error=NULL WHERE id=?",result.get("duplicate").equals(true)?"DUPLICATE":"SUCCESS",result.get("recordId"),rowId);
        }catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException(e);}
    }
    private Long classification(String value,Map<String,String> aliases){try{return Long.valueOf(aliases.getOrDefault(value,value));}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"未知分类值："+value);}}
    private Long department(long source){var value=jdbc.queryForObject("SELECT department_id FROM tb_data_source WHERE id=?",Long.class,source);InputChecks.require(value!=null,"中心导入请选择绑定部门的来源");return value;}
    Map<String,Object> receive(Authentication a,IntakeService.Entry entry,String scope,String key){var existing=jdbc.queryForList("SELECT record_id FROM tb_intake_receipt WHERE scope=? AND external_key=?",Long.class,scope,key);if(!existing.isEmpty())return Map.of("recordId",existing.getFirst(),"duplicate",true);var draft=intake.save(a,null,entry,null);var record=intake.submit(a,draft.id(),draft.version());long id=((Number)record.get("id")).longValue();jdbc.update("INSERT INTO tb_intake_receipt(scope,external_key,record_id) VALUES (?,?,?)",scope,key,id);return Map.of("recordId",id,"duplicate",false);}
    public Object credentials(Authentication a){accounts.administrator(a);return jdbc.queryForList("SELECT id,name,department_id,source_id,special_report,enabled FROM tb_external_credential ORDER BY id DESC");}
    public record Credential(String name,long departmentId,long sourceId,boolean specialReport){}
    @Transactional public Object credential(Authentication a,Credential c){lock();var actor=accounts.administrator(a);InputChecks.text(c.name(),100,"凭据名称");InputChecks.require(jdbc.queryForObject("SELECT COUNT(*) FROM tb_data_source WHERE id=? AND enabled=1 AND (department_id IS NULL OR department_id=?)",Long.class,c.sourceId(),c.departmentId())==1,"来源与部门不符");InputChecks.require(jdbc.queryForObject("SELECT COUNT(*) FROM tb_department WHERE id=? AND enabled=1 AND department_type='DEPARTMENT'",Long.class,c.departmentId())==1,"部门无效");String token=UUID.randomUUID()+"-"+UUID.randomUUID();long id=JdbcIds.insert(jdbc,"INSERT INTO tb_external_credential(token_hash,name,department_id,source_id,special_report,owner_id) VALUES (?,?,?,?,?,?)",hashes.fingerprint(token),c.name(),c.departmentId(),c.sourceId(),c.specialReport(),actor.id());audit.record(actor,"EXTERNAL_CREDENTIAL",id,null,c);return Map.of("id",id,"token",token);}
    @Transactional public void disable(Authentication a,long id){lock();var actor=accounts.administrator(a);jdbc.update("UPDATE tb_external_credential SET enabled=0 WHERE id=?",id);audit.record(actor,"EXTERNAL_CREDENTIAL",id,null,Map.of("enabled",false));}
    public record External(String externalId,IntakeService.Entry payload){}
    public void validateCredential(String token){
        if(jdbc.queryForObject("SELECT COUNT(*) FROM tb_external_credential c JOIN tb_user u ON u.id=c.owner_id JOIN tb_department d ON d.id=c.department_id JOIN tb_data_source s ON s.id=c.source_id WHERE c.token_hash=? AND c.enabled=1 AND u.enabled=1 AND d.enabled=1 AND s.enabled=1 AND (s.department_id IS NULL OR s.department_id=c.department_id)",Long.class,hashes.fingerprint(token))!=1)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"凭据无效或已停用");
    }
    @Transactional public Object external(String token,External item){lock();var c=jdbc.queryForList("SELECT c.*,u.username,d.name AS department_name FROM tb_external_credential c JOIN tb_user u ON u.id=c.owner_id JOIN tb_department d ON d.id=c.department_id JOIN tb_data_source s ON s.id=c.source_id WHERE c.token_hash=? AND c.enabled=1 AND d.enabled=1 AND s.enabled=1 AND u.enabled=1 AND (s.department_id IS NULL OR s.department_id=c.department_id)",hashes.fingerprint(token)).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"凭据无效或已停用"));
        InputChecks.text(item.externalId(),200,"外部编号");InputChecks.require(item.payload()!=null,"缺少事件内容");var e=item.payload();var roles=new ArrayList<>(List.of("DEPARTMENT_REPORTER"));if(Boolean.TRUE.equals(c.get("special_report")))roles.add("SPECIAL_REPORTER");var actor=new AccountService.Account(((Number)c.get("owner_id")).longValue(),c.get("username").toString(),"外部接入",((Number)c.get("department_id")).longValue(),c.get("department_name").toString(),roles);var auth=new AccountService.TrustedIntakeToken(actor);
        var entry=new IntakeService.Entry(e.personName(),e.idCard(),e.phone(),e.eventTime(),e.description(),((Number)c.get("source_id")).longValue(),e.categoryId(),e.disputeId(),null);
        var result=receive(auth,entry,"EXTERNAL:"+c.get("source_id"),hashes.fingerprint(item.externalId()));jdbc.update("INSERT INTO tb_external_receipt(credential_id,external_id,payload,record_id) VALUES (?,?,?,?)",c.get("id"),item.externalId(),encode(item),result.get("recordId"));return result;
    }
    public void externalFailure(String token,External item,String error){var ids=jdbc.queryForList("SELECT id FROM tb_external_credential WHERE token_hash=? AND enabled=1",Long.class,hashes.fingerprint(token));if(!ids.isEmpty())jdbc.update("INSERT INTO tb_external_receipt(credential_id,external_id,payload,error) VALUES (?,?,?,?)",ids.getFirst(),item==null?null:item.externalId(),encode(item),error);}
    public Object receipts(Authentication a){intake.analyst(a);return jdbc.queryForList("SELECT r.*,c.name FROM tb_external_receipt r JOIN tb_external_credential c ON c.id=r.credential_id ORDER BY r.id DESC LIMIT 500");}
}
